# prune_local <dir> <name>: keep only the newest keep generations (name.1 .. name.keep).
prune_local() {
  local dir=$1 name=$2 keep f n
  keep=$(get_keep) || return 1
  for f in "$dir/$name".*; do
    n=${f##*/"$name".}
    case $n in ''|*[!0-9]*) continue ;; esac
    [ "$n" -gt "$keep" ] && rm -f -- "$f"
  done
  return 0
}''')
