}

# prune_archive <archive dir> <name>: keep only the newest keep name.<date> files.
prune_archive() {
  local archive=$1 name=$2 keep f i=0
  keep=$(get_keep) || return 1
  for f in $(ls "$archive" | grep -E "^$(printf %s "$name" | sed 's/[.[\\*^$]/\\&/g')\\.[0-9]+$" | sort -r); do
